import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-students',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <h1 style="font-size:24px;font-weight:700;">Students</h1>
      <button class="btn btn-primary">+ Add Student</button>
    </div>
    <div class="card"><table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Course</th><th>Status</th></tr></thead><tbody>
      <tr *ngFor="let s of students"><td>{{s.id}}</td><td>{{s.name}}</td><td>{{s.email}}</td><td>{{s.course}}</td>
      <td><span class="badge badge-success">{{s.status}}</span></td></tr>
    </tbody></table></div>
  `
})
export class StudentsComponent {
  students = [
    { id: 1, name: 'John Doe', email: 'john@example.com', course: 'Java Full Stack', status: 'Active' },
    { id: 2, name: 'Jane Smith', email: 'jane@example.com', course: 'Java Placement', status: 'Active' },
    { id: 3, name: 'Bob Lee', email: 'bob@example.com', course: 'Digital Marketing', status: 'Inactive' },
  ];
}
